{{!-- Styling parameters: class, avatarClass, contentClass, titleClass, descriptionClass, metaClass --}}
{{#with this as |ghostcnStyles|}}
{{!--
  Component: Author Card
  Usage: In post context {{> "components/author-card"}} or {{#primary_author}}{{> "components/author-card"}}{{/primary_author}}
--}}
<section class="gh-author-card{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}">
    {{#if profile_image}}
    <img src="{{img_url profile_image size="m"}}" alt="{{name}}" class="gh-author-avatar{{#if ghostcnStyles.avatarClass}} {{ghostcnStyles.avatarClass}}{{/if}}" />
    {{else}}
    <div class="gh-author-avatar-fallback{{#if ghostcnStyles.avatarClass}} {{ghostcnStyles.avatarClass}}{{/if}}">
        {{name.[0]}}
    </div>
    {{/if}}

    <div class="gh-author-details{{#if ghostcnStyles.contentClass}} {{ghostcnStyles.contentClass}}{{/if}}">
        <div class="gh-author-heading">
            <h4 class="gh-author-name{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">
                <a href="{{url}}" >{{name}}</a>
            </h4>
            {{#if count.posts}}
            <span class="gh-author-post-count">
                {{plural count.posts empty="0 posts" singular="% post" plural="% posts"}}
            </span>
            {{/if}}
        </div>

        {{#if bio}}
        <p class="gh-author-bio{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{bio}}</p>
        {{/if}}

        <div class="gh-author-meta{{#if ghostcnStyles.metaClass}} {{ghostcnStyles.metaClass}}{{/if}}">
            {{#if location}}
            <span class="gh-author-location">📍 {{location}}</span>
            {{/if}}
            {{#if website}}
            <a href="{{website}}" target="_blank" rel="noopener noreferrer" class="gh-author-link">Website</a>
            {{/if}}
            {{#if twitter}}
            <a href="{{social_url type="twitter"}}" target="_blank" rel="noopener noreferrer" class="gh-author-link">Twitter/X</a>
            {{/if}}
            {{#if facebook}}
            <a href="{{social_url type="facebook"}}" target="_blank" rel="noopener noreferrer" class="gh-author-link">Facebook</a>
            {{/if}}
        </div>
    </div>
</section>
{{/with}}

/* ghostcn: Author Card Styles */
.gh-author-card {
    box-sizing: border-box;
    font-family: inherit;
    font-size: 16px;
    line-height: 1.5;
    isolation: isolate;
    background-color: var(--card, #ffffff);
    color: var(--card-foreground, #09090b);
    border: 1px solid var(--border, #e4e4e7);
    border-radius: min(var(--radius, 0.5em), 1.5em);
    padding: 1.5em;
    margin: 2em auto;
    max-width: 42em;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1.25em;
    box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.05);
}

.gh-author-card *,
.gh-author-card *::before,
.gh-author-card *::after {
    box-sizing: border-box;
}

@media (min-width: 640px) {
    .gh-author-card {
        flex-direction: row;
        align-items: flex-start;
    }
}

.gh-author-avatar {
    width: 5em;
    height: 5em;
    border-radius: 9999px;
    object-fit: cover;
    border: 2px solid var(--border, #e4e4e7);
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

.gh-author-avatar-fallback {
    width: 5em;
    height: 5em;
    border-radius: 9999px;
    background-color: var(--muted, #f4f4f5);
    color: var(--foreground, #09090b);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5em;
    font-weight: 700;
    border: 2px solid var(--border, #e4e4e7);
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

.gh-author-details {
    flex: 1;
    text-align: center;
}

@media (min-width: 640px) {
    .gh-author-details {
        text-align: left;
    }
}

.gh-author-name {
    font-size: 1.25em;
    font-weight: 700;
    letter-spacing: -0.025em;
    margin: 0;
    color: var(--foreground, #09090b);
}

.gh-author-name a {
    color: inherit;
    text-decoration: none;
    transition: color 0.15s ease;
}

.gh-author-name:hover {
    color: var(--primary, var(--ghost-accent-color, #18181b));
}

.gh-author-bio {
    color: var(--muted-foreground, #71717a);
    font-size: 0.875em;
    line-height: 1.5;
    margin: 0.5em 0 1em;
}

.gh-author-meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 1em;
    font-size: 0.75em;
    color: var(--muted-foreground, #71717a);
}

.gh-author-meta a {
    color: var(--primary, var(--ghost-accent-color, #18181b));
    text-decoration: none;
}

.gh-author-meta a:hover {
    text-decoration: underline;
}

.gh-author-heading { display: flex; flex-direction: column; justify-content: space-between; gap: 0.5em; margin-bottom: 0.5em; }
.gh-author-post-count { border-radius: 9999px; padding: 0.25em 0.625em; background: var(--muted); color: var(--muted-foreground); font-size: 0.75em; font-weight: 500; }
.gh-author-location { display: inline-flex; align-items: center; gap: 0.25em; }
@media (min-width: 640px) { .gh-author-heading { flex-direction: row; align-items: center; } .gh-author-meta { justify-content: flex-start; } }
